import fs from'node:fs';import assert from'node:assert/strict';import crypto from'node:crypto';import{createCommon}from'../create-common.mjs';import{defaultState}from'../src/State.mjs';
const m=createCommon(),s=defaultState(),pos=m.positions,faces=m.faces,hash=v=>crypto.createHash('sha256').update(v).digest('hex'),neutral=m.compute(s).slice(),zeroHash=hash(neutral),rows=[];const maxDiff=(a,b)=>{let d=0;for(let i=0;i<a.length;i++)d=Math.max(d,Math.abs(a[i]-b[i]));return d;};
for(const [group,count,value]of[['rotation',12,.12],['translation',3,.004]])for(let i=0;i<count;i++){const p=defaultState();p.gnm[group][i]=value;const out=m.compute(p).slice(),max=maxDiff(out,neutral);assert(max>1e-7,group+' '+i+' must actually move mesh');assert.equal(m.positions,pos);assert.equal(m.faces,faces);assert.equal(hash(m.compute(p)),hash(out));rows.push({source:'GNM',group,index:i,amplitude:value,maxDisplacementMetres:max,repeatedByteExact:true});}
const inactive=defaultState();inactive.owners.headRig='body';inactive.gnm.rotation[1]=.35;inactive.gnm.translation[0]=.02;assert.equal(hash(m.compute(inactive)),zeroHash);inactive.mhr.identity[0]=1;inactive.mhr.expression[0]=.7;inactive.mhr.pose[7]=.2;inactive.anny.facialActions[m.anny.facialActionLabels[0]]=.8;assert.equal(hash(m.compute(inactive)),zeroHash);
const g=defaultState();g.gnm.rotation[1]=.15;g.anny.pose.head=[20,30,10];const owned=m.compute(g).slice();const h=structuredClone(g);h.anny.pose.head=[-20,20,5];assert.equal(hash(m.compute(h)),hash(owned));h.owners.headRig='body';assert(maxDiff(m.compute(h),owned)>1e-3);h.owners.headRig='gnm';assert.equal(hash(m.compute(h)),hash(owned));
const combined=defaultState();combined.anny.phenotypes.weight=.8;combined.anny.localChanges[m.anny.localChangeLabels.find(x=>/stomach|torso|breast/.test(x))||m.anny.localChangeLabels[0]]=.3;combined.anny.pose['upperarm01.L']=[15,20,-25];combined.gnm.identity[0]=.4;combined.gnm.expression[200]=1;combined.gnm.rotation[7]=.1;combined.gnm.translation[2]=.004;const expected=m.compute(combined).slice(),archive=JSON.parse(JSON.stringify(m.archive()));m.compute(defaultState());assert.equal(hash(m.restore(archive)),hash(expected));assert.throws(()=>m.restore({...archive,adapterFingerprint:'f'.repeat(64)}));assert.equal(hash(m.positions),hash(expected));const bad=structuredClone(combined);bad.gnm.translation[0]=1e300;assert.throws(()=>m.compute(bad));assert.equal(hash(m.positions),hash(expected));assert.deepEqual(m.state,combined);
const report={passed:true,stage:'native channels and state contract; head/body transfer not complete',nativeGNMPoseCases:rows,gnmJointLabels:m.gnm.meta.jointNames,neutralHash:zeroHash,topologySHA256:m.canonical.topologySha256,fixedPositionAndIndexObjects:true,inactiveHeadRigAndMHRAndAnnyFacialInert:true,headRigSwitchRestores:true,officialAnnyRotvecBodyActive:true,explicitHeadJointOwnership:true,archiveExact:true,invalidArchiveAndNumericalStateRollbackExact:true,adapterFingerprint:m.adapterFingerprint,coverage:m.coverage,notBrowserOrVisualValidation:true};fs.writeFileSync('research/native-channel-report.json',JSON.stringify(report,null,2));console.log({passed:true,gnmPoseCases:rows.length,neutralHash:zeroHash,fingerprint:m.adapterFingerprint,fullCombinedComplete:false});
